  constructor(props) {
    super(props);
    this.notification = new UINotificationService();
    this.uiModelService = new UIModalService();
    this.tabId = 'tab-' + this.props.tabIndex;
  }

  onSelectActionTab = evt => {
    this.props.onSelectActionTab(evt.currentTarget.value);
  };
  onEnterActionTab = () => {
  };
  onLeaveActionTab = () => {
  };
  onSegmentCreated = id => {
  };
  onSegmentUpdated = id => {
  };
  onSegmentDeleted = id => {
  };
  onSegmentSelected = id => {
  };
  onSelectModel = model => {
  };

  segmentInfo = () => {
    return currentSegmentsInfo(this.props.servicesManager.services.segmentationService).info;
  };
